var r = msg._report || {};
var dbRows = (msg.payload && msg.payload[0] && msg.payload[0].n != null) ? msg.payload[0].n : null;
var serverUrl = env.get('SERVER_URL') || global.get('pcServerUrl') || 'https://api.smartgreen.kr';
return {
    method: 'POST',
    url: serverUrl + '/internal/maintenance-report',
    headers: { 'Content-Type': 'application/json', 'x-api-key': env.get('SENSOR_API_KEY') || global.get('sensorApiKey') || '' },
    payload: { farmId: r.farmId, deletedRows: r.deletedRows, retentionDays: r.retentionDays, dbRows: dbRows, ranAt: r.ranAt },
    requestTimeout: 8000
};
